(() => {
  const { scene } = window.__three
  const px = (img, u, v) => {
    if (!img || !img.width) return null
    const c = document.createElement('canvas'); c.width = img.width; c.height = img.height
    const x = c.getContext('2d'); if (!x) return null
    x.drawImage(img, 0, 0)
    const d = x.getImageData(Math.min(img.width - 1, Math.round(u * img.width)), Math.min(img.height - 1, Math.round(v * img.height)), 1, 1).data
    return [d[0], d[1], d[2]]
  }
  let dome = null
  scene.traverse(o => { if (!dome && o.isMesh && o.material && o.material.map && o.geometry && o.geometry.type === 'SphereGeometry') dome = o })
  const bg = scene.background && scene.background.image ? scene.background.image : null
  const domeImg = dome ? dome.material.map.image : null
  const s = window.__store.getState()
  console.log('[skyprobe] ' + JSON.stringify({
    weather: s.weather, hour: s.manualHour, mode: s.cameraMode,
    domeSize: domeImg ? domeImg.width + 'x' + domeImg.height : null,
    // v: 0 = zenith row, 0.5 = horizon row, 0.75 = 45 deg below (where the orbit camera looks)
    domeZenith: px(domeImg, 0.5, 0.02), domeHorizon: px(domeImg, 0.5, 0.49), domeBelow: px(domeImg, 0.5, 0.75),
    bgSize: bg ? bg.width + 'x' + bg.height : null,
    bgZenith: px(bg, 0.5, 0.02), bgHorizon: px(bg, 0.5, 0.49), bgGround: px(bg, 0.5, 0.75),
  }))
})()

